import{_ as i,c as t,o as l,ae as a}from"./chunks/framework.DMK_uHmU.js";const p=JSON.parse('{"title":"Content Search User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Search/user-search.md","filePath":"Search/user-search.md"}'),o={name:"Search/user-search.md"};function s(n,e,r,c,h,u){return l(),t("div",null,e[0]||(e[0]=[a('<h1 id="content-search-user-guide" tabindex="-1">Content Search User Guide <a class="header-anchor" href="#content-search-user-guide" aria-label="Permalink to &quot;Content Search User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#content-search-user-guide">Content Search User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-content-search">Accessing Content Search</a></li><li><a href="#search-interface">Search Interface</a></li><li><a href="#searching-content">Searching Content</a><ul><li><a href="#selecting-a-knowledge-base">Selecting a Knowledge Base</a></li><li><a href="#entering-search-queries">Entering Search Queries</a></li><li><a href="#submitting-searches">Submitting Searches</a></li></ul></li><li><a href="#search-results">Search Results</a><ul><li><a href="#results-display">Results Display</a></li><li><a href="#result-information">Result Information</a></li><li><a href="#ranking-system">Ranking System</a></li></ul></li><li><a href="#filtering-results">Filtering Results</a><ul><li><a href="#content-type-filter">Content Type Filter</a></li><li><a href="#filter-options">Filter Options</a></li></ul></li><li><a href="#viewing-content">Viewing Content</a><ul><li><a href="#document-viewer">Document Viewer</a></li><li><a href="#pdf-documents">PDF Documents</a></li><li><a href="#video-files">Video Files</a></li><li><a href="#text-based-files">Text-Based Files</a></li><li><a href="#html-files">HTML Files</a></li></ul></li><li><a href="#no-results-state">No Results State</a></li><li><a href="#loading-states">Loading States</a></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Content Search feature provides a powerful way to search through Knowledge Base content using natural language queries. This dedicated search interface allows you to find relevant documents, videos, and other content items across your organization&#39;s knowledge repositories. Unlike the AI Assistant which provides conversational answers, Content Search directly shows you the source documents that contain the information you need.</p><h2 id="accessing-content-search" tabindex="-1">Accessing Content Search <a class="header-anchor" href="#accessing-content-search" aria-label="Permalink to &quot;Accessing Content Search&quot;">​</a></h2><p>Content Search is accessible to users with various roles:</p><ul><li>User</li><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to the Content section in the main menu</li><li>Select &quot;Search&quot; from the dropdown menu</li><li>The search interface will load with the Knowledge Base selector</li></ol><h2 id="search-interface" tabindex="-1">Search Interface <a class="header-anchor" href="#search-interface" aria-label="Permalink to &quot;Search Interface&quot;">​</a></h2><p>The Content Search interface consists of these major components:</p><ol><li><strong>Header</strong>: Contains the title &quot;Search Content by Knowledge Base&quot; and description</li><li><strong>Search Controls</strong>: Knowledge Base selector, search input field, and search button</li><li><strong>Filter Controls</strong>: Options to filter results by content type</li><li><strong>Results Area</strong>: Displays search results with relevant excerpts and metadata</li><li><strong>Document Viewer</strong>: Full-screen drawer that opens when viewing content</li></ol><h2 id="searching-content" tabindex="-1">Searching Content <a class="header-anchor" href="#searching-content" aria-label="Permalink to &quot;Searching Content&quot;">​</a></h2><h3 id="selecting-a-knowledge-base" tabindex="-1">Selecting a Knowledge Base <a class="header-anchor" href="#selecting-a-knowledge-base" aria-label="Permalink to &quot;Selecting a Knowledge Base&quot;">​</a></h3><p>Before searching, you must select a Knowledge Base to search within:</p><ol><li>Click the &quot;KB&quot; button on the left side of the search bar</li><li>A dropdown menu appears showing available Knowledge Bases</li><li>Each Knowledge Base shows: <ul><li>Avatar with initials</li><li>Name (displayed in uppercase)</li><li>Brief description</li></ul></li><li>Click on any Knowledge Base to select it</li><li>The button text updates to show the selected Knowledge Base name</li></ol><h3 id="entering-search-queries" tabindex="-1">Entering Search Queries <a class="header-anchor" href="#entering-search-queries" aria-label="Permalink to &quot;Entering Search Queries&quot;">​</a></h3><p>To search effectively:</p><ol><li>Type your question or keywords in the search field</li><li>Use natural language questions for best results <ul><li>Example: &quot;What is the company policy on remote work?&quot;</li><li>Example: &quot;quarterly financial report 2024&quot;</li></ul></li><li>Be specific to narrow results</li><li>Keep queries concise but complete</li></ol><h3 id="submitting-searches" tabindex="-1">Submitting Searches <a class="header-anchor" href="#submitting-searches" aria-label="Permalink to &quot;Submitting Searches&quot;">​</a></h3><p>To execute your search:</p><ol><li>After entering your query, either: <ul><li>Press Enter key</li><li>Click the search icon button</li></ul></li><li>The system will display a loading indicator while searching</li><li>Results will appear below the search bar</li><li>The number of results found appears in a badge</li></ol><h2 id="search-results" tabindex="-1">Search Results <a class="header-anchor" href="#search-results" aria-label="Permalink to &quot;Search Results&quot;">​</a></h2><h3 id="results-display" tabindex="-1">Results Display <a class="header-anchor" href="#results-display" aria-label="Permalink to &quot;Results Display&quot;">​</a></h3><p>Search results appear in a vertical list below the search controls:</p><ol><li>Each result is displayed in a card-like format</li><li>Results are ordered by relevance score</li><li>Empty state message appears if no results are found</li><li>A count of total results appears at the top of the list</li></ol><h3 id="result-information" tabindex="-1">Result Information <a class="header-anchor" href="#result-information" aria-label="Permalink to &quot;Result Information&quot;">​</a></h3><p>Each result contains detailed information:</p><ol><li><strong>Document Icon</strong>: Shows the file type (PDF, Word, Excel, etc.)</li><li><strong>Document Title</strong>: Clickable title to open the document</li><li><strong>Excerpt</strong>: Text snippet showing relevant content with context</li><li><strong>Metadata</strong>: File extension, creation date, and update date</li><li><strong>Relevance Score</strong>: Numerical ranking of how relevant the document is</li></ol><p>File types are identified by distinctive icons:</p><ul><li>PDF: Document icon</li><li>Word: Word document icon</li><li>Excel: Spreadsheet icon</li><li>PowerPoint: Presentation icon</li><li>Text: Text file icon</li><li>CSV: Database icon</li><li>HTML: Code icon</li><li>Video: Video icon</li><li>Audio: Headphones icon</li></ul><h3 id="ranking-system" tabindex="-1">Ranking System <a class="header-anchor" href="#ranking-system" aria-label="Permalink to &quot;Ranking System&quot;">​</a></h3><p>Each result shows a relevance score:</p><ol><li>Score appears as a button in the right column</li><li>Values range from 1-100 (higher is more relevant)</li><li>Represents how closely the content matches your query</li><li>Based on sophisticated vector search algorithms</li><li>Scores above 70 typically indicate strong matches</li></ol><h2 id="filtering-results" tabindex="-1">Filtering Results <a class="header-anchor" href="#filtering-results" aria-label="Permalink to &quot;Filtering Results&quot;">​</a></h2><h3 id="content-type-filter" tabindex="-1">Content Type Filter <a class="header-anchor" href="#content-type-filter" aria-label="Permalink to &quot;Content Type Filter&quot;">​</a></h3><p>After receiving search results, you can filter by content type:</p><ol><li>Click the &quot;Type&quot; button in the top-right area</li><li>A dropdown menu appears with content type options</li><li>Select a type to filter the results list</li><li>The button text updates to show the current filter</li><li>To restore all results, select &quot;All Content&quot;</li></ol><h3 id="filter-options" tabindex="-1">Filter Options <a class="header-anchor" href="#filter-options" aria-label="Permalink to &quot;Filter Options&quot;">​</a></h3><p>Available filter options include:</p><ul><li><strong>All Content</strong>: Shows all document types (default)</li><li><strong>PDF</strong>: Only PDF documents</li><li><strong>MS Word</strong>: Word documents (.doc, .docx)</li><li><strong>MS Excel</strong>: Excel spreadsheets (.xls, .xlsx)</li><li><strong>Power Point</strong>: PowerPoint presentations (.ppt, .pptx)</li><li><strong>Text File</strong>: Plain text files (.txt)</li><li><strong>CSV</strong>: Comma Separated Value files</li><li><strong>JSON</strong>: JSON data files</li><li><strong>Web Html</strong>: HTML files</li><li><strong>Video</strong>: Video files</li><li><strong>Audio</strong>: Audio files</li><li><strong>MarkDown</strong>: MD files</li></ul><h2 id="viewing-content" tabindex="-1">Viewing Content <a class="header-anchor" href="#viewing-content" aria-label="Permalink to &quot;Viewing Content&quot;">​</a></h2><h3 id="document-viewer" tabindex="-1">Document Viewer <a class="header-anchor" href="#document-viewer" aria-label="Permalink to &quot;Document Viewer&quot;">​</a></h3><p>To view document content:</p><ol><li>Click on a document title in the results list</li><li>A full-screen drawer opens containing the document</li><li>The drawer header shows the document name</li><li>Content is rendered using an appropriate viewer based on file type</li><li>Close the drawer using the X button in the top-right corner</li></ol><h3 id="pdf-documents" tabindex="-1">PDF Documents <a class="header-anchor" href="#pdf-documents" aria-label="Permalink to &quot;PDF Documents&quot;">​</a></h3><p>When viewing PDF documents:</p><ol><li>The WebViewer component loads to display the document</li><li>Relevant text from your search may be highlighted</li><li>Navigation controls allow browsing through pages</li><li>The viewer automatically adapts to light/dark mode</li></ol><h3 id="video-files" tabindex="-1">Video Files <a class="header-anchor" href="#video-files" aria-label="Permalink to &quot;Video Files&quot;">​</a></h3><p>When viewing video files:</p><ol><li>A video player appears with standard controls: <ul><li>Play/pause</li><li>Volume adjustment</li><li>Playback position scrubber</li></ul></li><li>Video plays automatically when opened</li><li>Downloads are disabled for security</li><li>An accordion section below shows &quot;Video Transcription&quot; (when available)</li></ol><h3 id="text-based-files" tabindex="-1">Text-Based Files <a class="header-anchor" href="#text-based-files" aria-label="Permalink to &quot;Text-Based Files&quot;">​</a></h3><p>When viewing text files (CSV, RTF, JSON, XML):</p><ol><li>Content is displayed in a formatted preview</li><li>Syntax highlighting is applied for code formats</li><li>The MdPreview component renders the content</li><li>Vuepress theme is applied for consistent styling</li></ol><h3 id="html-files" tabindex="-1">HTML Files <a class="header-anchor" href="#html-files" aria-label="Permalink to &quot;HTML Files&quot;">​</a></h3><p>When viewing HTML files:</p><ol><li>Raw HTML code is displayed by default</li><li>A message appears offering to view the rendered page</li><li>Click &quot;View Live Page&quot; to open the HTML in a new browser tab</li><li>This approach maintains security while providing access to both code and rendered content</li></ol><h2 id="no-results-state" tabindex="-1">No Results State <a class="header-anchor" href="#no-results-state" aria-label="Permalink to &quot;No Results State&quot;">​</a></h2><p>When no search results are found or before the first search:</p><ol><li>A prominent &quot;No Search Results Found&quot; message appears</li><li>The message includes an icon and explanatory text</li><li>Instructions remind you to: <ul><li>Select a Knowledge Base</li><li>Enter a search into the prompt</li></ul></li><li>This state helps guide users to take appropriate action</li></ol><h2 id="loading-states" tabindex="-1">Loading States <a class="header-anchor" href="#loading-states" aria-label="Permalink to &quot;Loading States&quot;">​</a></h2><p>Visual indicators appear during search operations:</p><ol><li><p><strong>Search Loading</strong>:</p><ul><li>A circular progress spinner appears in the center</li><li>&quot;AI Searching Content. Please wait.&quot; text is displayed</li><li>The spinner uses the primary theme color</li></ul></li><li><p><strong>File Loading</strong>:</p><ul><li>When opening a document that requires processing</li><li>A spinner with &quot;File is loading. Please wait.&quot; message</li><li>Disappears once content is ready to view</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective content searching:</p><ol><li><p><strong>Query Formulation</strong>:</p><ul><li>Use specific, descriptive terms</li><li>Phrase questions naturally</li><li>Include key terms that would appear in target documents</li><li>Consider synonyms for important concepts</li></ul></li><li><p><strong>Knowledge Base Selection</strong>:</p><ul><li>Choose the most relevant Knowledge Base for your topic</li><li>Use broader Knowledge Bases for general searches</li><li>Select specialized Knowledge Bases for domain-specific queries</li></ul></li><li><p><strong>Result Evaluation</strong>:</p><ul><li>Check relevance scores to gauge match quality</li><li>Review excerpts to determine if content meets needs</li><li>Open documents with scores above 70 first</li><li>Try alternative search terms if results aren&#39;t relevant</li></ul></li><li><p><strong>Filter Usage</strong>:</p><ul><li>Start broad and then apply filters if needed</li><li>Use type filters when looking for specific document formats</li><li>Return to &quot;All Content&quot; if filtered results are too limited</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: No results found for a search</p><ul><li>Try using different search terms or synonyms</li><li>Ensure you&#39;ve selected the correct Knowledge Base</li><li>Check if your query is too specific</li><li>Verify the content you&#39;re looking for exists in the selected KB</li></ul><p><strong>Issue</strong>: Knowledge Base selector shows no options</p><ul><li>Wait a moment as Knowledge Bases might still be loading</li><li>Check if you have permissions to access Knowledge Bases</li><li>Try refreshing the page</li><li>Contact your administrator if the issue persists</li></ul><p><strong>Issue</strong>: Document doesn&#39;t open when clicked</p><ul><li>Wait a moment as large documents take time to load</li><li>Check if your browser supports the file format</li><li>Try a different browser if issues persist</li><li>Ensure you have permissions to view the document</li></ul><p><strong>Issue</strong>: Video playback issues</p><ul><li>Check if your browser supports HTML5 video</li><li>Ensure you have a stable internet connection</li><li>Try reducing video quality if available</li><li>Some security settings may restrict media playback</li></ul><p><strong>Issue</strong>: Text files appear empty or corrupted</p><ul><li>Wait for file loading to complete</li><li>Check if file encoding is standard UTF-8</li><li>Try clicking the refresh button</li><li>Some heavily formatted text files may not display correctly</li></ul><p><strong>Issue</strong>: HTML files don&#39;t display properly</p><ul><li>Use the &quot;View Live Page&quot; button to see the rendered page</li><li>Raw HTML code is shown by default for security reasons</li><li>External resources in the HTML may be blocked</li><li>Some interactive elements may not function in the viewer</li></ul><hr><p>For additional assistance with Content Search, please contact your system administrator or refer to the platform documentation.</p>',82)]))}const g=i(o,[["render",s]]);export{p as __pageData,g as default};
